 private void loadNote()throws Exception{noteBaseline=store.note(id);JSONObject draft=drafts.optJSONObject(id);filling=true;noteEditor.setText(draft==null?noteBaseline.optString("text"):draft.optString("text"));if(draft!=null)noteBaseline=draft.getJSONObject("baseline");filling=false;}
