 private void historyReload()throws Exception{historyRows=new JSONArray();historyAdapter.clear();JSONArray rows=store.backup().getJSONArray("snapshots");for(int i=rows.length()-1;i>=0;i--){JSONObject r=rows.getJSONObject(i);if(!id.equals(r.getString("instrumentId")))continue;historyRows.put(r);historyAdapter.add(r.getString("capturedAt")+" · "+r.getString("id"));}historyAdapter.notifyDataSetChanged();}
