 private void colors(View v){if(v instanceof LinearLayout||v instanceof ScrollView||v instanceof ListView)v.setBackgroundColor(dark?0xff101a27:0xffffffff);if(v instanceof TextView)((TextView)v).setTextColor(ink());if(v instanceof EditText)((EditText)v).setHintTextColor(dark?0xff9eb3cb:0xff65778b);if(v instanceof Button)v.setBackgroundTintList(ColorStateList.valueOf(dark?0xff26394f:0xffe9eef5));if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)colors(g.getChildAt(i));}}
 private AtomicFile stateFile(){try{File database=getContext().getDatabasePath(store.getDatabaseName()).getCanonicalFile(),parent=database.getParentFile(),cache=getContext().getCacheDir().getCanonicalFile();if(new File(store.getDatabaseName()).isAbsolute()&&parent!=null&&parent.getParentFile().equals(cache)&&parent.getName().matches("company-profile-v86-[A-Za-z0-9-]{1,64}"))return new AtomicFile(new File(parent,"research-view.json"));}catch(IOException ignored){}return new AtomicFile(new File(getContext().getFilesDir(),"stock-research-"+store.getDatabaseName().replaceAll("[^a-zA-Z0-9_-]","_")+".json"));}
 private JSONObject fullState()throws Exception{return new JSONObject().put("schema","stock-research-view/v1").put("instrumentId",id).put("drafts",drafts).put("current",current).put("reading",reading).put("mode",mode).put("pending",pending).put("incoming",incoming).put("baseline",importBaseline).put("profileHistorical",profileHistorical).put("profileSource",profileKind).put("profileOffset",profileOffset).put("profileOriginalMode",profileOriginalMode);}
 JSONObject saveState()throws Exception{persist();return new JSONObject().put("schema","stock-research-view/v1").put("privateState",true);}
 private void persist()throws Exception{byte[] bytes=fullState().toString().getBytes(StandardCharsets.UTF_8);StockResearchModel.need(bytes.length<=64*1024*1024,"研究视图状态超过64MB，请分批导入或先导出，未截断草稿");AtomicFile f=stateFile();FileOutputStream out=null;try{out=f.startWrite();out.write(bytes);f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 void restoreState(JSONObject s){if(s.optBoolean("privateState")){diskRestore();return;}safe(()->{StockResearchModel.need("stock-research-view/v1".equals(s.optString("schema")),"研究视图状态无效");cancelProfile(false);profileHistorical=s.optBoolean("profileHistorical");profileOffset=Math.max(0,Math.min(8*StockProfileModel.LIMIT,s.optInt("profileOffset")));String kind=s.optString("profileSource","CompanySurvey");if(Arrays.asList(StockProfileModel.KINDS).contains(kind)){profileKind=kind;profileSource.setSelection(Arrays.asList(StockProfileModel.KINDS).indexOf(kind));}profileOriginalMode=s.optBoolean("profileOriginalMode");drafts=s.getJSONObject("drafts");id=s.optString("instrumentId");if(!id.isEmpty()){StockResearchModel.identity(id);identity.setText(id);loadNote();current=StockResearchModel.bundle(id,s.getJSONObject("current"));showBundle(StockResearchModel.bundle(id,s.getJSONObject("reading")));historyReload();}pending=s.optBoolean("pending");if(pending){incoming=StockResearchModel.decode(s.getJSONObject("incoming").toString());importBaseline=s.getJSONObject("baseline");previewReader.setText("恢复原待确认预览\n"+StockResearchModel.preview(incoming,importBaseline).toString(2)+"\n"+incoming.toString(2));confirm.setEnabled(true);}mode=Math.max(0,Math.min(5,s.optInt("mode",4)));views();});}
 private void diskRestore(){if(!stateFile().getBaseFile().exists())return;safe(()->{try(InputStream in=stateFile().openRead();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){StockResearchModel.need(bytes.size()+n<=64*1024*1024,"研究视图状态过大");bytes.write(buffer,0,n);}restoreState(new JSONObject(bytes.toString("UTF-8")));}});}
 protected void onDetachedFromWindow(){cancelProfile(false);safe(()->persist());super.onDetachedFromWindow();}

