  profilePane=new LinearLayout(getContext());profilePane.setOrientation(VERTICAL);profilePane.setTag("stockResearchProfilePane");LinearLayout actions=new LinearLayout(getContext());profilePane.addView(actions);profileUpdate=button(actions,"更新源","stockResearchProfileUpdate",()->updateProfile());profileCancel=button(actions,"取消","stockResearchProfileCancel",()->cancelProfile(true));button(actions,"概览","stockResearchProfileSummaryMode",()->{profileOriginalMode=false;profileViews();});button(actions,"原字段","stockResearchProfileOriginalMode",()->{profileOriginalMode=true;renderProfileOriginal();profileViews();});
