 private void profileViews(){if(profileRaw==null)return;profileSummaryScroll.setVisibility(profileOriginalMode?GONE:VISIBLE);profileRaw.setVisibility(profileOriginalMode?VISIBLE:GONE);}
 private void renderProfile()throws Exception{if(profileSummary==null)return;JSONObject p=reading.optJSONObject("companyProfile");try{if(p==null)profileSummary.setText(reading.has("companyProfileError")?"本机主营缓存读取失败，原件保留："+reading.optString("companyProfileError"):"先选择完整证券身份。现有主营缓存可直接阅读；显式更新读取公司公开源。");else{StockProfileModel.validate(id,p);profileSummary.setText((profileHistorical?"历史冻结公司资料 · 原来源时点保持\n\n":"")+StockProfileModel.overview(p));}}catch(Exception e){profileSummary.setText("主营原资料不能解释："+e.getMessage());}boolean supported=false;try{supported=!id.isEmpty()&&StockProfileModel.supported(id);}catch(Exception ignored){}profileUpdate.setEnabled(profileEnabled&&supported&&!profileHistorical&&profileToken.isEmpty());profileCancel.setEnabled(!profileToken.isEmpty());renderProfileOriginal();profileViews();}
 private void renderProfileOriginal()throws Exception{if(profileOriginal==null)return;JSONObject p=reading.optJSONObject("companyProfile");try{if(p==null)profileText="尚无完整来源原字段";else{StockProfileModel.validate(id,p);profileText=StockProfileModel.original(p,profileKind);}}catch(Exception e){profileText="主营原字段不可读："+e.getMessage();}profileOffset=Math.max(0,Math.min(profileOffset,Math.max(0,profileText.length()-1)));profileOriginal.setText(profileText.substring(profileOffset,Math.min(profileText.length(),profileOffset+32768)));profilePrevious.setEnabled(profileOffset>0);profileNext.setEnabled(profileOffset+32768<profileText.length());profileOriginalScroll.scrollTo(0,0);}
 private void cancelProfile(boolean announce){String token=profileToken;profileToken="";if(profiles!=null&&!token.isEmpty())profiles.cancel(token);safe(()->renderProfile());if((announce||!token.isEmpty())&&state!=null)state.setText("公司资料读取已取消，未保存新缓存。");}
 private boolean profileOwner(String selected,String token){return isShown()&&getWindowVisibility()==VISIBLE&&mode==5&&!profileHistorical&&id.equals(selected)&&profileToken.equals(token);}
 private void updateProfile()throws Exception{StockProfileModel.need(profiles!=null&&profileEnabled&&isShown()&&mode==5&&!profileHistorical&&!id.isEmpty()&&StockProfileModel.supported(id)&&profileToken.isEmpty(),"请在当前证券主营概况页明确更新");String selected=id,token=UUID.randomUUID().toString();profileToken=token;renderProfile();state.setText("正在读取三个公司公开源；可明确取消。");try{profiles.start(token,selected,()->profileOwner(selected,token),(returned,packet,error)->safe(()->{if(!id.equals(selected)||!profileToken.equals(token))return;profileToken="";if(error.isEmpty()){StockProfileModel.validate(selected,packet);current.put("companyProfile",packet);current.remove("companyProfileError");reading.put("companyProfile",new JSONObject(packet.toString()));reading.remove("companyProfileError");profileOffset=0;renderProfile();if(documents.getCheckedItemPosition()<0)reader.setText(StockResearchModel.overview(reading));persist();state.setText("本次公司源读取结束；各源结果分别显示，失败源保留原缓存。");}else{renderProfile();state.setText("公司资料未更新："+error);}}));}catch(Exception e){profileToken="";renderProfile();throw e;}}
 protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(visibility!=VISIBLE&&profilePane!=null)cancelProfile(false);}
